import{_ as i,o as a,c as t,ag as n}from"./chunks/framework.PVHj0As1.js";const e="/pub-blog/assets/image-20250826230645973.BdbmRC8K.png",l="/pub-blog/assets/image-20250104222001043.DGhWIzn1.png",h="/pub-blog/assets/image-20250104223622772.Bq_mjgjQ.png",p="/pub-blog/assets/image-20250104224722034.BbJRh47v.png",r="data:image/png;base64,",k="data:image/png;base64,",d="data:image/png;base64,",g="/pub-blog/assets/image-20250104230514600.CXyq0qUb.png",E="/pub-blog/assets/image-20250104230945457.QMvC6AmG.png",o="/pub-blog/assets/image-20250104235451185.BYjsGymX.png",y="/pub-blog/assets/image-20250104234845265.rO9wTK7l.png",c="/pub-blog/assets/image-20250104235533508.C7aqFbt0.png",m="/pub-blog/assets/image-20250104235642059.B4cH-cEw.png",C="/pub-blog/assets/image-20250105000141244.DH1yyV8O.png",A="/pub-blog/assets/PixPin_2025-01-05_00-07-08.TDSXTsfB.gif",b="/pub-blog/assets/PixPin_2025-01-05_00-08-20._G6y1G6q.gif",u="/pub-blog/assets/image-20250822223258675.CJHnmYEl.png",F="/pub-blog/assets/wanshaoweixin.DWzIcicW.jpg",w=JSON.parse('{"title":"可可图片编辑 HarmonyOS（4）图片裁剪-canvas","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（4）图片裁剪/可可图片编辑 HarmonyOS（4）图片裁剪.md","filePath":"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（4）图片裁剪/可可图片编辑 HarmonyOS（4）图片裁剪.md","lastUpdated":1757677612000,"__rawMarkdown":"# 可可图片编辑 HarmonyOS（4）图片裁剪-canvas\\n\\n## 前言\\n\\n**可可图片编辑** 实现了图片的裁剪功能，效果如图所示。这里的核心技术是使用了canvas。\\n\\n![image-20250826230645973](assets/image-20250826230645973.png)\\n\\n## Canvas 入门\\n\\nCanvas提供画布组件，用于自定义绘制图形，开发者使用CanvasRenderingContext2D对象和OffscreenCanvasRenderingContext2D对象在Canvas组件上进行绘制，绘制对象可以是基础形状、文本、图片等，canvas也可以实现对图片到裁剪，并且还可以把canvas上描绘的图形下载保存成图片。本章节主要讲解下canvas的基本使用。\\n\\n## 基本使用\\n\\ncanvas 的基本使用分为 4 步：\\n\\n1. 设置是否抗锯齿*抗锯齿（Anti - aliasing）是一种在数字图形处理中使用的技术，主要用于减少图像中因为像素有限而产生的锯齿状边缘的现象*\\n2. 创建画布上下文\\n3. 渲染画布组件\\n4. 在画布上描绘图案\\n\\n```jsx\\n@Entry\\n@Component\\nstruct Index {\\n  // 1 用来配置CanvasRenderingContext2D对象的参数，包括是否开启抗锯齿，true表明开启抗锯齿。\\n  private settings: RenderingContextSettings = new RenderingContextSettings(true)\\n  // 2 用来创建CanvasRenderingContext2D对象，通过在canvas中调用CanvasRenderingContext2D对象来绘制。\\n  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)\\n\\n  build() {\\n      // 3 在canvas中调用CanvasRenderingContext2D对象。\\n    Column(){\\n      Canvas(this.context)\\n        .width(\'100%\')\\n        .height(\'100%\')\\n        .backgroundColor(\'#F5DC62\')\\n        .onReady(() => {\\n          // 4 可以在这里绘制内容。\\n          this.context.strokeRect(50, 50, 200, 150);\\n        })\\n    }\\n    .width(\'100%\')\\n    .height(\'100%\')\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n5. 效果\\n\\n![image-20250104222001043](assets/image-20250104222001043.png)\\n\\n## canvas 常见用法\\n\\ncanvas 的核心思想是将想要的图形如，直线、圆圈、矩形等图形描绘到画布上。如果想要呈现出比较酷炫的效果，做法是：\\n\\n1. 描绘图形\\n2. 擦除画布\\n3. 计算数值-重新描绘图形\\n4. 擦除画布\\n5. 。。。\\n\\n通过以上过程实现动画效果\\n\\n![image-20250104223622772](assets/image-20250104223622772.png)\\n\\n### canvas 的坐标系\\n\\n在 canvas 中画图形都是基于坐标系来进行的。 左上角为起点。\\n\\n![image-20250104224722034](assets/image-20250104224722034.png)\\n\\n### 描绘图形\\n\\ncanvas 中内置的常见的描绘图形的方法有以下：\\n\\n1. 直线\\n2. 矩形\\n3. 弧形\\n4. 文本\\n5. 图像\\n6. ...\\n\\n### 直线\\n\\n描绘直线可以使用：\\n\\n1. 定起点 `moveTo`\\n2. 定终点 `lineTo`\\n3. 开始描绘 `stroke`\\n\\n```jsx\\nthis.context.moveTo(10, 10);\\nthis.context.lineTo(100, 100);\\nthis.context.stroke();\\n```\\n\\n![image-20250104224216771](assets/image-20250104224216771.png)\\n\\n### 矩形\\n\\n可以使用直线`lineTo`自己画成一个矩形。也可以直接使用 `strokeRect`直接生成矩形\\n\\n**lineTo 画矩形**\\n\\n```jsx\\nthis.context.moveTo(10, 10);\\nthis.context.lineTo(300, 10);\\nthis.context.lineTo(300, 300);\\nthis.context.lineTo(10, 300);\\n//   自动闭环\\nthis.context.closePath();\\n//   开始描述 将路径的当前点移回到路径的起点，当前点到起点间画一条直线\\nthis.context.stroke();\\n```\\n\\n![image-20250104225516822](assets/image-20250104225516822.png)\\n\\n**strokeRect 画矩形**\\n\\n```jsx\\n// this.context.strokeRect(x, y, 宽度, 高度);\\nthis.context.strokeRect(50, 50, 200, 150);\\n```\\n\\n![image-20250104225643875](assets/image-20250104225643875.png)\\n\\n### 弧形\\n\\n弧形可以使用 `arc` 和 `arcTo` 来描绘\\n\\n**arc**\\n\\n> arc(x: number, y: number, radius: number, startAngle: number, endAngle: number, counterclockwise?: boolean)\\n\\n| 参数名           | 类型    | 必填 | 说明                                                         |\\n| :--------------- | :------ | :--- | :----------------------------------------------------------- |\\n| x                | number  | 是   | 弧线圆心的 x 坐标值。默认单位：vp。                          |\\n| y                | number  | 是   | 弧线圆心的 y 坐标值。默认单位：vp。                          |\\n| radius           | number  | 是   | 弧线的圆半径。默认单位：vp。                                 |\\n| startAngle       | number  | 是   | 弧线的起始弧度。单位：弧度                                   |\\n| endAngle         | number  | 是   | 弧线的终止弧度。单位：弧度                                   |\\n| counterclockwise | boolean | 否   | 是否逆时针绘制圆弧。true:逆时针方向绘制椭圆。false:顺时针方向绘制椭圆。默认值：false。 |\\n\\n这里需要注意的是 arc 使用的单位是**弧度**不是**角度**\\n\\n```\\n一圈 = 360角度 =  2 * Math.PI\\n半圈 = 180角度 =  Math.PI ≈ 3.14\\n```\\n\\n观察以下效果\\n\\n![image-20250104230514600](assets/image-20250104230514600.png)\\n\\n> 100,75 是圆心坐标\\n>\\n> 50 是半径\\n>\\n> 0 是开始的弧度\\n>\\n> 6.28 ≈ 2 \\\\* Math.PI = 一圈\\n\\n---\\n\\narc 是从正右方向开始旋转的。\\n\\n```jsx\\nthis.context.beginPath();\\nthis.context.arc(100, 75, 50, 0, 3.14 / 2);\\nthis.context.stroke();\\n```\\n\\n![image-20250104230945457](assets/image-20250104230945457.png)\\n\\n**arcTo**\\n\\n> arcTo(x1: number, y1: number, x2: number, y2: number, radius: number)\\n\\n| 参数名 | 类型   | 必填 | 说明                                    |\\n| :----- | :----- | :--- | :-------------------------------------- |\\n| x1     | number | 是   | 第一个控制点的 x 坐标值。默认单位：vp。 |\\n| y1     | number | 是   | 第一个控制点的 y 坐标值。默认单位：vp。 |\\n| x2     | number | 是   | 第二个控制点的 x 坐标值。默认单位：vp。 |\\n| y2     | number | 是   | 第二个控制点的 y 坐标值。默认单位：vp。 |\\n| radius | number | 是   | 圆弧的圆半径值。默认单位：vp。          |\\n\\n![image-20250104235451185](assets/image-20250104235451185.png)\\n\\n```jsx\\nthis.context.beginPath();\\nthis.context.strokeStyle = \\"#000000\\";\\nthis.context.lineWidth = 3;\\nthis.context.moveTo(360, 20);\\nthis.context.arcTo(360, 170, 110, 170, 150);\\nthis.context.stroke();\\n```\\n\\n**辅助理解**\\n\\n想象一下，我们有一个起点（即当前路径的最后一个点），然后有三个更多的点：两个控制点 (x1, y1) 和 (x2, y2)，以及由 `radius`\\n\\n定义的一个圆心。`arcTo` 会创建一条从起点到第二个控制点 (x2, y2) 的圆弧，这条圆弧是位于以 `radius` 为半径的圆周上的一部\\n\\n分。该圆弧会在起点和第一个控制点 (x1, y1) 之间形成一个切线，并且也会在第二个控制点 (x2, y2) 和圆弧的终点之间形成一个切线。\\n\\n![image-20250104234845265](assets/image-20250104234845265.png)\\n\\n### 文本\\n\\n1. **strokeText**表示描边的图形\\n2. **fillText** 表示填充的图形，还有其他**fill**，**fillRect**等也表示填充。\\n\\n**strokeText**\\n\\n```typescript\\n  this.context.font = \'55px sans-serif\'\\n  this.context.strokeText(\\"Hello World!\\", 20, 60)\\n```\\n\\n![image-20250104235533508](assets/image-20250104235533508.png)\\n\\n**fillText**\\n\\n```typescript\\nthis.context.font = \'55px sans-serif\'\\nthis.context.fillText(\\"Hello World!\\", 20, 60)\\n```\\n\\n![image-20250104235642059](assets/image-20250104235642059.png)\\n\\n### 图像\\n\\n**drawImage**可以把图像描绘到画布上，很多的在线图形合成效果都可以利用该功能实现\\n\\n> drawImage(image: ImageBitmap | PixelMap, dx: number, dy: number): void\\n>\\n> drawImage(image: ImageBitmap | PixelMap, dx: number, dy: number, dw: number, dh: number): void\\n>\\n> drawImage(image: ImageBitmap | PixelMap, sx: number, sy: number, sw: number, sh: number, dx: number, dy: number, dw: number, dh: number): void\\n\\n| 参数名 | 类型                                                         | 必填 | 说明                                                         |\\n| :----- | :----------------------------------------------------------- | :--- | :----------------------------------------------------------- |\\n| image  | [ImageBitmap](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/ts-components-canvas-imagebitmap-V13)或[PixelMap](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V13/js-apis-image-V13#pixelmap7) | 是   | 图片资源，请参考 ImageBitmap 或 PixelMap。                   |\\n| sx     | number                                                       | 是   | 裁切源图像时距离源图像左上角的 x 坐标值。image 类型为 ImageBitmap 时，默认单位：vp。image 类型为 PixelMap 时，单位：px。 |\\n| sy     | number                                                       | 是   | 裁切源图像时距离源图像左上角的 y 坐标值。image 类型为 ImageBitmap 时，默认单位：vp。image 类型为 PixelMap 时，单位：px。 |\\n| sw     | number                                                       | 是   | 裁切源图像时需要裁切的宽度。image 类型为 ImageBitmap 时，默认单位：vp。image 类型为 PixelMap 时，单位：px。 |\\n| sh     | number                                                       | 是   | 裁切源图像时需要裁切的高度。image 类型为 ImageBitmap 时，默认单位：vp。image 类型为 PixelMap 时，单位：px。 |\\n| dx     | number                                                       | 是   | 绘制区域左上角在 x 轴的位置。默认单位：vp。                  |\\n| dy     | number                                                       | 是   | 绘制区域左上角在 y 轴的位置。默认单位：vp。                  |\\n| dw     | number                                                       | 是   | 绘制区域的宽度。当绘制区域的宽度和裁剪图像的宽度不一致时，将图像宽度拉伸或压缩为绘制区域的宽度。默认单位：vp。 |\\n| dh     | number                                                       | 是   | 绘制区域的高度。当绘制区域的高度和裁剪图像的高度不一致时，将图像高度拉伸或压缩为绘制区域的高度。默认单位：vp。 |\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  private settings: RenderingContextSettings = new RenderingContextSettings(true)\\n  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)\\n  private img: ImageBitmap = new ImageBitmap(\\"/images/example.jpg\\")\\n\\n  build() {\\n    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {\\n      Canvas(this.context)\\n        .width(\'100%\')\\n        .height(\'100%\')\\n        .backgroundColor(\'#ffff00\')\\n        .onReady(() => {\\n          this.context.drawImage(this.img, 0, 0)\\n          this.context.drawImage(this.img, 0, 150, 300, 100)\\n          this.context.drawImage(this.img, 0, 0, 500, 500, 0, 300, 400, 200)\\n        })\\n    }\\n    .width(\'100%\')\\n    .height(\'100%\')\\n  }\\n}\\n```\\n\\n![image-20250105000141244](assets/image-20250105000141244.png)\\n\\n## canvas 浅尝动态效果 1\\n\\n```jsx\\nconst width = px2vp(display.getDefaultDisplaySync().availableWidth) * 0.9;\\nconst height = width;\\nlet x = 0;\\nlet y = 0;\\nsetInterval(() => {\\n  this.context.strokeRect(x, y, 100, 100);\\n  x++;\\n  y++;\\n}, 20);\\n```\\n\\n![PixPin_2025-01-05_00-07-08](assets/PixPin_2025-01-05_00-07-08.gif)\\n\\n## canvas 浅尝动态效果 2\\n\\n```jsx\\nconst width = px2vp(display.getDefaultDisplaySync().availableWidth) * 0.9;\\nconst height = width;\\nlet x = 0;\\nlet y = 0;\\nsetInterval(() => {\\n  // 清理画布\\n  this.context.strokeRect(x, y, 100, 100);\\n  x++;\\n  y++;\\n}, 20);\\n```\\n\\n![PixPin_2025-01-05_00-08-20](assets/PixPin_2025-01-05_00-08-20.gif)\\n\\n## canvas 属性 一览\\n\\n| 名称                     | 说明                                                         |\\n| ------------------------ | ------------------------------------------------------------ |\\n| fillStyle                | 设置绘制的填充色，支持多种类型及对应创建方式，有默认值。     |\\n| lineWidth                | 设置绘制线条的宽度，有默认值及取值限制。                     |\\n| strokeStyle              | 设置线条的颜色，支持多种类型及对应创建方式，有默认值。       |\\n| lineCap                  | 指定线端点的样式，有可选值及默认值。                         |\\n| lineJoin                 | 指定线段间相交的交点样式，有可选值及默认值。                 |\\n| miterLimit               | 设置斜接面限制值，有默认值及取值限制。                       |\\n| font                     | 设置文本绘制中的字体样式，包含多种可选参数及默认值。         |\\n| textAlign                | 设置文本绘制中的文本对齐方式，有可选值及默认值。             |\\n| textBaseline             | 设置文本绘制中的水平对齐方式，有可选值及默认值。             |\\n| globalAlpha              | 设置透明度，有默认值。                                       |\\n| lineDashOffset           | 设置画布的虚线偏移量，有默认值。                             |\\n| globalCompositeOperation | 设置合成操作的方式，有可选值及默认值。                       |\\n| shadowBlur               | 设置绘制阴影时的模糊级别，有默认值及取值限制。               |\\n| shadowColor              | 设置绘制阴影时的阴影颜色，有默认值。                         |\\n| shadowOffsetX            | 设置绘制阴影时和原有对象的水平偏移值，有默认值。             |\\n| shadowOffsetY            | 设置绘制阴影时和原有对象的垂直偏移值，有默认值。             |\\n| imageSmoothingEnabled    | 设置绘制图片时是否进行图像平滑度调整，有默认值。             |\\n| height                   | 表示组件高度，有默认单位。                                   |\\n| width                    | 表示组件宽度，有默认单位。                                   |\\n| imageSmoothingQuality    | 设置图像平滑度，有默认值。                                   |\\n| direction                | 设置绘制文字时使用的文字方向，有默认值。                     |\\n| filter                   | 设置图像的滤镜，支持多种滤镜效果，有默认值。                 |\\n| canvas                   | 获取和 CanvasRenderingContext2D 关联的 Canvas 组件的 FrameNode 实例，<br />可监听可见状态，默认值为 null。 |\\n\\n## canvas 方法 一览\\n\\n| 名称                    | 说明                                                         |\\n| ----------------------- | ------------------------------------------------------------ |\\n| fillRect                | 推测用于进行图形填充相关操作（通常是填充矩形区域）           |\\n| strokeRect              | 推测用于绘制矩形边框相关操作（通常是绘制矩形的轮廓）         |\\n| clearRect               | 推测用于清除指定矩形区域的内容                               |\\n| fillText                | 推测用于对文本进行填充操作（比如设置文本填充颜色等相关样式填充） |\\n| strokeText              | 推测用于绘制文本的轮廓相关操作                               |\\n| measureText             | 推测用于测量文本相关的尺寸等属性                             |\\n| stroke                  | 一般用于绘制图形的轮廓、线条等（按常规语义理解）             |\\n| beginPath               | 通常用于开始定义一个新的路径，后续可基于此路径进行图形绘制等操作 |\\n| moveTo                  | 常用来将画笔移动到指定坐标位置，作为绘制路径的起始点等操作   |\\n| lineTo                  | 一般用于从当前画笔位置绘制直线到指定坐标位置，构建路径内容   |\\n| closePath               | 通常用于闭合当前正在绘制的路径，使路径形成封闭图形           |\\n| createPattern           | 可能用于创建某种图案（比如重复平铺的图案等）用于绘制等       |\\n| bezierCurveTo           | 大概率用于绘制贝塞尔曲线，通过控制点来定义曲线形状           |\\n| quadraticCurveTo        | 推测用于绘制二次贝塞尔曲线，指定控制点来确定曲线走向         |\\n| arc                     | 一般用于绘制圆弧，通过圆心、半径、起始角度、结束角度等参数来定义 |\\n| arcTo                   | 常用来绘制与两条切线相切的圆弧，按给定条件确定圆弧形状       |\\n| ellipse                 | 用于绘制椭圆图形，需指定相关参数如圆心坐标、长半轴、短半轴等 |\\n| rect                    | 可用于绘制矩形，指定矩形的左上角坐标、宽度、高度等参数       |\\n| fill                    | 用于对已绘制的图形或者指定区域进行填充操作                   |\\n| clip                    | 可能用于设置裁剪区域，后续绘制内容只在裁剪区域内显示         |\\n| reset12+                | 从名称看可能是在特定版本（12+）中用于重置某些状态或设置的操作 |\\n| saveLayer12+            | 在特定版本（12+）里可能用于保存图层相关状态等操作            |\\n| restoreLayer12+         | 在特定版本（12+）里对应于之前保存图层状态进行恢复的操作      |\\n| resetTransform          | 推测用于重置图形变换相关的设置（比如旋转、缩放等变换）       |\\n| rotate                  | 用于将图形进行旋转操作，需指定旋转角度等参数                 |\\n| scale                   | 用于对图形进行缩放操作，指定横向和纵向的缩放比例             |\\n| transform               | 一般用于对图形进行多种变换（如平移、旋转、缩放等组合变换）的设置 |\\n| setTransform            | 可能用于设置图形的变换矩阵，来确定图形的变换情况             |\\n| getTransform            | 推测用于获取当前图形的变换相关信息（比如变换矩阵等）         |\\n| translate               | 用于将图形进行平移操作，指定在横、纵坐标方向平移的距离       |\\n| drawImage               | 通常用于在画布上绘制图像，指定图像源及绘制位置等参数         |\\n| createImageData         | 可能用于创建图像数据对象（比如像素数据等相关内容）           |\\n| getPixelMap             | 推测用于获取像素映射相关的数据（比如图像像素的分布等情况）   |\\n| setPixelMap             | 大概是用于设置像素映射相关数据，改变图像像素表现等           |\\n| getImageData            | 一般用于获取图像的像素数据等具体信息内容                     |\\n| putImageData            | 通常是将获取到的图像数据（如像素数据）重新应用到画布等位置   |\\n| setLineDash             | 可能用于设置线条的虚线样式，指定虚线的长度、间隔等参数       |\\n| getLineDash             | 推测用于获取当前线条所设置的虚线样式相关参数                 |\\n| transferFromImageBitmap | 从名称看可能是与从图像位图进行数据转移相关操作               |\\n| toDataURL               | 通常用于将画布等内容转换为可以表示图像数据的 URL 格式        |\\n| restore                 | 一般用于恢复之前保存的某些状态（如画布状态等）               |\\n| save                    | 常用来保存当前画布等相关的状态，以便后续恢复使用             |\\n| createLinearGradient    | 用于创建线性渐变对象，可用于图形的渐变填充等操作             |\\n| createRadialGradient    | 用于创建径向渐变对象，定义从中心向外扩散的渐变效果           |\\n| createConicGradient     | 用于创建圆锥渐变对象，实现类似圆锥形状的渐变效果             |\\n\\n## 以往文章\\n\\n\\n\\n- [可可图片编辑 HarmonyOS 上架应用分享](https://mp.weixin.qq.com/s?__biz=MzI0NjY1MDY3Mg==&mid=2247489342&idx=1&sn=15f4872e080ee3f86efdc32d6edfd979&chksm=e813ff241c45844ae10e1fb352499b7253ae91ad932db71f17e86fa2251bb17251d5d840d1ab&scene=126&sessionid=1756092287&subscene=91&clicktime=1756092289&enterid=1756092289#rd)\\n- [可可图片编辑 HarmonyOS（2） 选择图片和保存到图库](https://mp.weixin.qq.com/s/dacDD763JhrLkIS1V8rrdg)\\n- [可可图片编辑 HarmonyOS（3） 应用间分享图片](https://mp.weixin.qq.com/s/n8kkdougB4lqDHjYC7co8g)\\n- [懂你的HarmonyOS知识库更新了，已经来到10970个文档了](https://mp.weixin.qq.com/s/sMd0CGe54T2Eya8dPaEn2A)\\n- [AI编程神器！Trae+Claude4.0 简单配置 让 HarmonyOS 开发效率飙升](https://mp.weixin.qq.com/s/AsieJTX8RkixgaKyDrzddg)\\n\\n\\n\\n\\n\\n## 近期活动\\n\\n最近想要想要考取 HarmonyOS 基础或者高级证书，或者快要获取的同学都可以点击这个链接，[加入我的班级](https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248)，考取成功有机会获得鸿蒙礼盒一份。\\n\\n![image-20250822223258675](assets/image-20250822223258675.png)\\n\\n\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多HarmonyOS相关的资讯。\\n\\n![wanshaoweixin](assets/wanshaoweixin.jpg)"}'),x={name:"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（4）图片裁剪/可可图片编辑 HarmonyOS（4）图片裁剪.md"};function B(v,s,f,I,Q,D){return a(),t("div",null,[...s[0]||(s[0]=[n("",92)])])}const M=i(x,[["render",B]]);export{w as __pageData,M as default};
